    if k not in G:
        G[k] = [[int(x) for x in r] for r in rowlist]

inp = G['Demo pair 1 input']
out = G['Demo pair 1 output']
h, w = len(inp), len(inp[0])

zero_rows = sorted([r for r in range(h) if all(inp[r][c] == 0 for c in range(w))])
zero_cols = sorted([c for c in range(w) if all(inp[r][c] == 0 for r in range(h))])

def get_ranges(zeros, max_idx):
    ranges = []
    start = 0
    for z in zeros:
        if start < z:
            ranges.append((start, min(z-1, max_idx)))
            start = z + 1
    if start <= max_idx:
            ranges.append((start, max_idx))
    return ranges

row_ranges = get_ranges(zero_rows, h-1)
col_ranges = get_ranges(zero_cols, w-1)

# Build a logical grid representation where each section has one "main value"
# This is the unique non-2 value at position rr[1]-1, cc[1]-1 (last cell of block)
logical_grid = {}

for i, rr in enumerate(row_ranges):
    for j, cc in enumerate(col_ranges):
        # Look at the last cell in the block (bottom-right corner area)
        last_cell_in = inp[rr[-1]][cc[-1]]
        if last_cell_in > 2:  # special value
            logical_grid[(i,j)] = {'val': last_cell_in, 'section': (i,j)}
        else:
            # Check if any cell in block has non-2 value
            for r in range(rr[0]+1, rr[1]):
                for c in range(cc[0]+1, cc[1]):
                    val = inp[r][c]
                    if val > 2:
                        logical_grid[(i,j)] = {'val': val}
                        break
                if (i,j) in logical_grid:
                    break
        if (i,j) not in logical_grid:
            logical_grid[(i,j)] = None

print("=== Logical grid values ===")
for (i,j), info in logical_grid.items():
    print(f"S({i},{j}): {info}")

# Now look at the structure - sections seem to form pairs
# Sections (0,2) and (0,3) both have value 3 -> they're adjacent horizontal neighbors
# Sections (1,1) and (1,4) have value 1 -> separated

print("\n=== Checking adjacency ===")
for (i,j), info in sorted(logical_grid.items()):
    if info is None:
        continue
    val = info['val']
    # Count same-value neighbors
    same_neighbors = 0
    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni, nj = i+di, j+dj
        if (ni,nj) in logical_grid and logical_grid[(ni,nj)]['val'] == val:
            same_neighbors += 1
    print(f"S({i},{j})={val}: {same_neighbors} same-valued neighbors")

